// 1. Function Declaration (hoisted — can call before declaration)
function greet(name) {
  return `Hello, ${name}!`;
}

// 2. Function Expression (not hoisted)
const greet2 = function(name) {
  return `Hello, ${name}!`;
};

// 3. Arrow Function — concise, no own 'this'
const greet3 = (name) => `Hello, ${name}!`;

// Arrow function with body
const greet4 = (name) => {
  const msg = `Hello, ${name}!`;
  return msg;
};

// Default parameters
const createUser = (name, role = 'viewer', active = true) => ({
  name, role, active
});

// Rest parameters — gather remaining args into array
const sum = (...nums) => nums.reduce((a, b) => a + b, 0);
sum(1, 2, 3, 4, 5); // 15

// Global scope
const globalVar = 'I am everywhere';

function outer() {
  const outerVar = 'outer scope'; // function scope

  if (true) {
    const blockVar = 'block scope'; // only inside this {}
    var varVar = 'function scope'; // var ignores blocks!
    console.log(blockVar); // ✅
  }
  console.log(varVar);   // ✅ var leaks out of block
  // console.log(blockVar); // ❌ ReferenceError

  function inner() {
    // inner can access outer's variables (lexical scope)
    console.log(outerVar); // ✅
    console.log(globalVar); // ✅
  }
  inner();
}

// Closure — the returned function 'remembers' count
function makeCounter(startFrom = 0) {
  let count = startFrom;

  return {
    increment() { count++; },
    decrement() { count--; },
    value()     { return count; }
  };
}

const counter1 = makeCounter(10);
const counter2 = makeCounter(0);

counter1.increment(); // count: 11
counter1.increment(); // count: 12
counter2.increment(); // count: 1 (independent closure!)

console.log(counter1.value()); // 12
console.log(counter2.value()); // 1

// Object destructuring
const { name, age, address: { city } = {} } = user;

// Array destructuring
const [first, second, ...rest] = [1, 2, 3, 4, 5];

// Destructuring in function params
const getDisplayName = ({ firstName, lastName, username }) =>
  firstName ? `${firstName} ${lastName}` : username;

// Spread operator
const arr1 = [1, 2, 3];
const arr2 = [4, 5, 6];
const combined = [...arr1, ...arr2];  // [1,2,3,4,5,6]

const obj1 = { a: 1, b: 2 };
const obj2 = { b: 99, c: 3 };
const merged = { ...obj1, ...obj2 }; // { a:1, b:99, c:3 }

// Optional chaining — avoids TypeError on undefined
const city = user?.address?.city;           // undefined if missing
const first2 = user?.friends?.[0]?.name;   // safe array access
const status = user?.getStatus?.();        // safe method call

// Nullish coalescing — only falls back on null/undefined
const displayName = user.name ?? 'Anonymous'; // not '' or 0

// Functions passed as arguments (callbacks)
const nums = [5, 3, 8, 1, 9, 2];
const sorted  = nums.sort((a, b) => a - b);    // compare fn
const evens   = nums.filter(n => n % 2 === 0);
const doubled = nums.map(n => n * 2);

// Functions returned from functions
const multiply = (factor) => (number) => number * factor;
const double   = multiply(2);
const triple   = multiply(3);

console.log(double(5));  // 10
console.log(triple(5));  // 15

// Composing functions
const compose = (...fns) => (x) => fns.reduceRight((v, f) => f(v), x);
const add1 = n => n + 1;
const times2 = n => n * 2;
const square = n => n * n;

const transform = compose(square, times2, add1);
transform(3); // square(times2(add1(3))) = square(8) = 64

// math.js — named exports
export const PI = 3.14159;
export function add(a, b) { return a + b; }
export const multiply = (a, b) => a * b;

// Default export (one per file)
export default function Calculator() { /* ... */ }

// user.js — mixed exports
export const createUser = (name, role) => ({ id: Date.now(), name, role });
export const deleteUser = (id) => { /* ... */ };

// main.js — importing
import Calculator from './math.js';           // default import
import { add, multiply, PI } from './math.js'; // named imports
import { add as sum } from './math.js';        // renamed import
import * as MathUtils from './math.js';        // namespace import

// Dynamic import (lazy loading)
const { parse } = await import('./parser.js');
